import{z as i,x as o,o as A,c as d,q as r,j as n,D as B,d as a,s as l,S as s,b as e}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"行情数据的清洗","description":"","frontmatter":{"title":"行情数据的清洗","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/de-marketdata-cleaning.md","filePath":"quant/de-marketdata-cleaning.md","lastUpdated":1791413859000}'),C={name:"quant/de-marketdata-cleaning.md"};function D(p,E,h,u,c,m){const t=o("Mermaid");return A(),d("div",null,[E[2]||(E[2]=r('<h1 id="行情数据的清洗" tabindex="-1">行情数据的清洗 <a class="header-anchor" href="#行情数据的清洗" aria-label="Permalink to &quot;行情数据的清洗&quot;">​</a></h1><div class="epigraph"><p>馈送给你的是撮合引擎的投影，不是一条干净序列；清洗的全部工作，是把「引擎说过什么」与「你想研究什么」之间的落差一一显式化。</p><footer>—— 据 NASDAQ TotalView-ITCH 消息规范；NYSE TAQ 成交条件字段的公开说明整理</footer></div><p><a href="/quant/de-tsdb-selection">上一课</a>把选型钉在查询形状上，数据有了住处；但落盘的字节还不是序列。行情清洗的缺口从这里开始：逐笔消息里有错误打印、重传重复、乱序到达、盘外成交与错误更正，全都长得像正常数据。清洗不改变事件，只把每个「看上去像」翻译成明确语义。本课写单日内的清洗——跨日界的调整是公司行动一课的对象。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>清洗要回答四个问题。<span class="marginnote">术语翻译：内容哈希就是把整条消息（时间、价格、量、标的等字段）压成一枚固定长度的「指纹」——两条消息指纹相同，几乎必然是同一条内容的重传。用「消息键 + 内容哈希」判重，比只比时间戳可靠得多，因为不同消息也可能落在同一毫秒里。</span><strong>消息级硬校验</strong>：负量、非正价、超出当日价格带的打印，通常是馈送或解码错误；量级小，但混进波动率估计就是一条假跳变。<span class="marginnote">数字实例：价格带可以直接用当日涨跌停（A 股 ±10%）当断言——10 元的股票打印出 11.5 元的成交，一条就越界，立刻入账剔除。没有这条断言，它混进日内收益率序列就是一次 +15% 的假跳变，把当日已实现波动率抬高数倍。</span><strong>去重与重排</strong>：行情协议的缺失与重传让同一条消息到达两次，乱序让到达序不等于撮合序；用毫秒时间戳给纳秒市场排序，并列序内的先后只能靠到达序，次序错了买卖方向分类就在临界处随机翻转。<strong>条件标记过滤</strong>：成交打印里相当一部分不是常规连续撮合——开盘竞价、大宗、交叉、错误更正各带专门标记（TAQ 的成交条件字段）；不过滤，开盘与收盘的已实现波动率被重复计入，日内季节性一半来自标记构成而非交易行为。<strong>快照对账</strong>：重建的簿与自报快照要对得上，负深度与交叉簿是重建错误，按<a href="/quant/lobster-itch-feed">LOBSTER 与 ITCH 行情</a>立下的不变量当数据测试失败处理，不许插值糊过去。</p><p><span class="marginnote">每类清洗动作都要留下计数账——过滤了多少硬错误、多少重复、多少非常规打印、多少并列序。账不全，就说不清一段序列「干净」到什么程度；回测异常时，这张账是第一个排查对象。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>管线按序五段，段与段之间只传带账目的中间结果。第一段硬校验，按字段级断言剔除坏行入账。第二段定序：主时钟用撮合引擎时间戳，到达时间只用于并列序破平；跨源数据先对时，见<a href="/quant/latency-budget">延迟预算</a>的口径，<a href="/quant/sip-vs-direct">SIP vs 直连行情</a>的结论在这里兑现——报价与成交不同源时，定序先坏。第三段去重：以消息键与内容哈希判重，重传与首传合并。第四段标记过滤：按研究用途决定保留集合——日内波动率只要常规连续成交，成交方向分类可以放宽，逐项写进数据字典。第五段对账：与交易所日终汇总对成交量、与快照对 BBO，超容差整段拒收并回放上游。</p>',8)),(A(),n(s,null,{default:B(()=>[l(t,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20RAW%5B%22%E8%90%BD%E7%9B%98%E7%9A%84%E9%80%90%E7%AC%94%E6%B6%88%E6%81%AF%22%5D%20--%3E%20V%5B%22%E7%A1%AC%E6%A0%A1%E9%AA%8C%EF%BC%9A%E8%B4%9F%E9%87%8F%E3%80%81%E5%9D%8F%E4%BB%B7%E3%80%81%E8%B6%8A%E7%95%8C%22%5D%0A%20%20V%20--%3E%20ORD%5B%22%E5%AE%9A%E5%BA%8F%EF%BC%9A%E6%92%AE%E5%90%88%E6%97%B6%E9%97%B4%E4%B8%BA%E4%B8%BB%EF%BC%8C%E5%88%B0%E8%BE%BE%E6%97%B6%E9%97%B4%E7%A0%B4%E5%B9%B3%22%5D%0A%20%20ORD%20--%3E%20DUP%5B%22%E5%8E%BB%E9%87%8D%EF%BC%9A%E6%B6%88%E6%81%AF%E9%94%AE%E5%8A%A0%E5%86%85%E5%AE%B9%E5%93%88%E5%B8%8C%22%5D%0A%20%20DUP%20--%3E%20COND%5B%22%E6%A0%87%E8%AE%B0%E8%BF%87%E6%BB%A4%EF%BC%9A%E6%8C%89%E7%94%A8%E9%80%94%E4%BF%9D%E7%95%99%E6%89%93%E5%8D%B0%E9%9B%86%E5%90%88%22%5D%0A%20%20COND%20--%3E%20REC%5B%22%E5%AF%B9%E8%B4%A6%EF%BC%9A%E6%88%90%E4%BA%A4%E6%B1%87%E6%80%BB%E4%B8%8E%20BBO%20%E5%BF%AB%E7%85%A7%22%5D%0A%20%20REC%20--%3E%7C%22%E8%B6%85%E5%AE%B9%E5%B7%AE%22%7C%20REPLAY%5B%22%E6%8B%92%E6%94%B6%E6%95%B4%E6%AE%B5%EF%BC%8C%E5%9B%9E%E6%94%BE%E4%B8%8A%E6%B8%B8%22%5D%0A%20%20REC%20--%3E%7C%22%E9%80%9A%E8%BF%87%22%7C%20CLEAN%5B%22%E5%B8%A6%E8%B4%A6%E7%9B%AE%E7%9A%84%E6%B8%85%E6%B4%81%E5%BA%8F%E5%88%97%22%5D%0A"})]),fallback:B(()=>[...E[0]||(E[0]=[a(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=e("h2",{id:"机制",tabindex:"-1"},[a("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=e("p",null,[a("清洗的本质是把三类「沉默的语义决定」显式化。其一，时钟决定因果：并列序内谁先谁后理论上不可识别，工程上必须选一个可重复的规则并声明它；换规则会改变成交方向分类与冲击估计，所以要像参数一样入版本。其二，标记决定样本空间：「市场」不是全部打印，而是被研究问题选中的子集，清洗把这个选择写成可审计的保留清单。"),e("span",{class:"marginnote"},"常见误区：初学者容易以为开盘竞价、大宗这些「非常规」打印是坏数据、一律删掉。它们不是错，只是不属于特定研究问题——波动率研究不要它们，成交方向分类反而可能要放宽保留。错不在数据，在于不声明保留清单就默认全收或全删。"),a("其三，对账决定可信域：抽查对得上的时段才可信，对不上的宁可整段丢弃也不修补——修补会在最需要数据的压力日引入最强的人为结构。入账让「这段序列怎么来的」成为可引用的事实，而不是手艺。")],-1)),(A(),n(s,null,{default:B(()=>[l(t,{id:"mermaid-29",class:"mermaid",graph:"flowchart%20TD%0A%20%20C1%5B%22%E5%86%B3%E5%AE%9A%E4%B8%80%3A%20%E7%94%A8%E5%93%AA%E4%B8%AA%E6%97%B6%E9%92%9F%22%5D%20--%3E%20E1%5B%22%E5%BD%B1%E5%93%8D%3A%20%E5%B9%B6%E5%88%97%E6%B6%88%E6%81%AF%E7%9A%84%E5%85%88%E5%90%8E%20%E2%86%92%20%E6%88%90%E4%BA%A4%E6%96%B9%E5%90%91%E5%88%86%E7%B1%BB%22%5D%0A%20%20C2%5B%22%E5%86%B3%E5%AE%9A%E4%BA%8C%3A%20%E4%BF%9D%E7%95%99%E5%93%AA%E4%BA%9B%E6%9D%A1%E4%BB%B6%E6%A0%87%E8%AE%B0%22%5D%20--%3E%20E2%5B%22%E5%BD%B1%E5%93%8D%3A%20%E6%A0%B7%E6%9C%AC%E7%A9%BA%E9%97%B4%20%E2%86%92%20%E6%B3%A2%E5%8A%A8%E7%8E%87%20%2F%20%E5%AD%A3%E8%8A%82%E6%80%A7%22%5D%0A%20%20C3%5B%22%E5%86%B3%E5%AE%9A%E4%B8%89%3A%20%E5%AF%B9%E4%B8%8D%E4%B8%8A%E5%AE%B9%E5%B7%AE%E6%80%8E%E4%B9%88%E5%8A%9E%22%5D%20--%3E%20E3%5B%22%E5%BD%B1%E5%93%8D%3A%20%E5%8F%AF%E4%BF%A1%E5%9F%9F%20%E2%86%92%20%E4%B8%A2%E5%BC%83%E8%80%8C%E9%9D%9E%E6%8F%92%E5%80%BC%22%5D%0A%20%20E1%20--%3E%20V%5B%22%E4%B8%89%E8%80%85%E9%83%BD%E8%A6%81%E6%98%BE%E5%BC%8F%E5%A3%B0%E6%98%8E%E5%B9%B6%E5%85%A5%E7%89%88%E6%9C%AC%22%5D%0A%20%20E2%20--%3E%20V%0A%20%20E3%20--%3E%20V%0A"})]),fallback:B(()=>[...E[1]||(E[1]=[a(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=r('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不重讲馈送与契约本身：消息语义见<a href="/quant/lobster-itch-feed">LOBSTER 与 ITCH 行情</a>，管道延迟见<a href="/quant/sip-vs-direct">SIP vs 直连行情</a>。清洗只处理单日内的字节；除权除息与代码变更会在日界上留下看似错误的跳价，那是下一课的对象，不要在这里当坏数据删掉。清洗也不承诺救回坏馈送：整段丢包、时钟漂移超容差的数据，丢弃是唯一正确动作。最后，清洗规则本身要版本化——规则一改，同一批原始数据变成另一段序列，这个绑定关系由版本化一课接管。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>清洗四问：硬校验、去重定序、标记过滤、快照对账，每段动作入账。</li><li>主时钟用撮合时间，到达时间只破平；跨源先对时，混源先坏定序。</li><li>「市场」是被保留清单选中的打印子集，清单可审计而非默认。</li><li>对不上容差的时段整段丢弃不修补；压力日最忌人为结构。</li><li>清洗规则随数据一起版本化，绑定关系交给下一课。</li><li>出处：NASDAQ TotalView-ITCH 消息规范；NYSE TAQ 成交条件字段说明；站内<a href="/quant/lobster-itch-feed">LOBSTER 与 ITCH 行情</a>与<a href="/quant/latency-budget">延迟预算</a>的口径。</li></ul>',4))])}const T=i(C,[["render",D]]);export{F as __pageData,T as default};
